import java.io.*;
import java.util.Arrays;

public class Main {
    static int[] dsuPar;
    static int[] parKRT;
    static int[] pathN;
    static long[] pathW;

    static int find(int x) {
        int r = x;
        while (dsuPar[r] != r) r = dsuPar[r];
        while (dsuPar[x] != r) { int nx = dsuPar[x]; dsuPar[x] = r; x = nx; }
        return r;
    }

    // menor índice i (mais raso) no caminho com peso <= T (array não-crescente)
    static int searchMin(long[] w, int d, long T) {
        int lo = 0, hi = d;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (w[mid] <= T) hi = mid; else lo = mid + 1;
        }
        return lo;
    }

    static int nextInt(DataInputStream in) throws IOException {
        int ret = 0, b = in.read();
        while (b != -1 && (b < '0' || b > '9')) b = in.read();
        if (b == -1) return -1;
        while (b >= '0' && b <= '9') { ret = ret * 10 + (b - '0'); b = in.read(); }
        return ret;
    }

    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int N = nextInt(in);
        int M = nextInt(in);
        int K = N * M;
        int[] val = new int[K];
        for (int i = 0; i < K; i++) val[i] = nextInt(in);

        long[] keys = new long[K];
        for (int i = 0; i < K; i++) keys[i] = (((long) val[i]) << 20) | i;
        Arrays.sort(keys);

        int maxNodes = 2 * K;
        dsuPar = new int[maxNodes];
        parKRT = new int[maxNodes];
        Arrays.fill(parKRT, -1);
        int[] wv = new int[maxNodes];
        long[] sumv = new long[maxNodes];
        boolean[] processed = new boolean[K];
        int[] rts = new int[4];
        int cnt = K;

        for (int i = 0; i < K; i++) { wv[i] = val[i]; sumv[i] = val[i]; }

        // Construção da Kruskal Reconstruction Tree (floresta) processando em ordem crescente de valor
        for (int ki = 0; ki < K; ki++) {
            int idx = (int) (keys[ki] & 1048575);
            int v = val[idx];
            int r = idx / M, c = idx - r * M;
            rts[0] = rts[1] = rts[2] = rts[3] = -1;
            int rc = 0;
            if (r > 0 && processed[idx - M]) {
                int t = find(idx - M);
                if (t != rts[0] && t != rts[1] && t != rts[2] && t != rts[3]) rts[rc++] = t;
            }
            if (r < N - 1 && processed[idx + M]) {
                int t = find(idx + M);
                if (t != rts[0] && t != rts[1] && t != rts[2] && t != rts[3]) rts[rc++] = t;
            }
            if (c > 0 && processed[idx - 1]) {
                int t = find(idx - 1);
                if (t != rts[0] && t != rts[1] && t != rts[2] && t != rts[3]) rts[rc++] = t;
            }
            if (c < M - 1 && processed[idx + 1]) {
                int t = find(idx + 1);
                if (t != rts[0] && t != rts[1] && t != rts[2] && t != rts[3]) rts[rc++] = t;
            }
            if (rc == 0) {
                dsuPar[idx] = idx; // começa componente próprio
            } else {
                int z = cnt++;
                wv[z] = v;
                sumv[z] = v;
