                }
                dsuPar[idx] = z;
            }
            processed[idx] = true;
        }

        // children em CSR
        int NN = cnt;
        int[] chStart = new int[NN + 1];
        for (int x = 0; x < NN; x++) if (parKRT[x] >= 0) chStart[parKRT[x] + 1]++;
        for (int x = 0; x < NN; x++) chStart[x + 1] += chStart[x];
        int[] chArr = new int[NN];
        int[] fillP = new int[NN];
