        // Para cada nó x:
        //  startN[x] = ancestral-or-self mais alto com peso <= peso(x)  (estado inicial do herói que começa em x)
        //  nextN[x]  = ancestral-or-self mais alto com peso <= soma(x)  (próximo salto do processo)
        int[] startN = new int[NN];
        int[] nextN = new int[NN];
        pathN = new int[NN + 1];
        pathW = new long[NN + 1];
        int[] stk = new int[NN + 1];
        int[] curP = new int[NN + 1];

        for (int R = 0; R < NN; R++) {
            if (parKRT[R] != -1) continue;
            int sp = 0;
            stk[0] = R; curP[0] = chStart[R];
            pathN[0] = R; pathW[0] = wv[R];
            startN[R] = pathN[searchMin(pathW, 0, wv[R])];
            nextN[R] = pathN[searchMin(pathW, 0, sumv[R])];
