                    pathN[sp] = y; pathW[sp] = wv[y];
                    startN[y] = pathN[searchMin(pathW, sp, wv[y])];
                    nextN[y] = pathN[searchMin(pathW, sp, sumv[y])];
                } else {
                    sp--;
                }
            }
        }

        // Simulação por ponto fixo (poder dobra/Fibonacci a cada salto => poucas iterações)
        long[] rf = new long[K];
        for (int c0 = 0; c0 < K; c0++) {
            int cu = startN[c0];
            while (nextN[cu] != cu) cu = nextN[cu];
            rf[c0] = sumv[cu];
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                sb.append(rf[i * M + j]);
                if (j + 1 < M) sb.append(' ');
            }
            sb.append('\n');
        }
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        pw.print(sb);
        pw.flush();
    }
